package glitch

import data.glitch_lib

# Define the keyword pattern for hard-coded credentials
keyword_pattern := "(?i)(password|secret_key|api_key|token|access_key|private_key|secret_value|admin_password|db_password|default_username|default_password|admin_credentials|root_password|encryption_key|signing_key|ssh_private_key|auth_token|bearer_token|shared_secret|environment|user_data|custom_data|startup_script|connection_string|db_url|username|endpoint_credentials|deploy_token|ci_cd_secret|webhook_secret|github_token)"

# Define default credential values
default_values := {
    "admin", "password", "root", "123456", "12345678", "123456789", "12345", "1234", "123", "12", "1", 
    "letmein", "welcome", "monkey", "qwerty", "abc123", "password1", "passw0rd", "zaq12wsx"
}

# Helper function to check if a string is a default value
is_default_value(str) {
    lower_str := lower(str)
    default_values[_] == lower_str
}

# Helper function to check if a node is a hard-coded literal (no variable references)
is_hardcoded_literal(node) {
    not glitch_lib.has_variable_reference(node)
}

# Check if a value expression contains hard-coded credentials in the context of a key
check_value(value_expr, key) {
    # Check if the key matches the keyword pattern
    regex.match(keyword_pattern, key)
    # Check the value expression
    check_value_expression(value_expr)
}

# Recursively check value expressions for hard-coded credentials
check_value_expression(value_expr) {
    value_expr.ir_type == "String"
    is_hardcoded_literal(value_expr)
} else {
    value_expr.ir_type == "Hash"
    check_hash_node(value_expr)
} else {
    value_expr.ir_type == "Array"
    check_array_node(value_expr)
}

# Check hash nodes for hard-coded credentials
check_hash_node(hash_node) {
    some key_expr, value_expr in hash_node.value
    key_expr.ir_type == "String"
    key := key_expr.value
    check_value(value_expr, key)
}

# Check array nodes for hard-coded credentials
check_array_node(array_node) {
    some element in array_node.value
    check_value_expression(element)
}

# Main rule to detect hard-coded credentials
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Walk through all attributes and variables in the parent
    walk(parent, [path, node])
    (node.ir_type == "Attribute" || node.ir_type == "Variable")

    key := node.name
    value := node.value

    # Check if the attribute/variable has a keyword name and contains hard-coded credentials
    check_value(value, key)

    # Determine if it's a default credential
    description := "Hard-coded credential found in attribute or variable. (CWE-798)"
    value.ir_type == "String"
    is_default_value(value.value)
    description := "Hard-coded default credential found in attribute or variable. (CWE-798)"

    result := {
        "type": "sec_hard_secr",
        "element": node,
        "path": parent.path,
        "description": description
    }
}

